import math
from itertools import combinations

def gcd(a, b):
    return math.gcd(a, b)

def gcd3(a, b, c):
    return gcd(a, gcd(b, c))

def is_good_set(U):
    a, b, c = U

    # Condition 1: GCD condition
    if gcd3(a, b, c) != 1:
        return False

    # Condition 2: Divisor condition
    # Since |U|=3, the third element must divide the product of the other two.
    # Pair (a, b) -> third element is c. Check c | ab
    if (a * b) % c != 0:
        return False

    # Pair (a, c) -> third element is b. Check b | ac
    if (a * c) % b != 0:
        return False

    # Pair (b, c) -> third element is a. Check a | bc
    if (b * c) % a != 0:
        return False

    return True

# Search for good sets U of size 3 where elements are < 20
limit = 20
good_sets_results = []

# Iterate through all combinations of 3 distinct numbers from {1, 2, ..., 19}
for U in combinations(range(1, limit), 3):
    if is_good_set(U):
        product = U[0] * U[1] * U[2]
        good_sets_results.append({
            'set': tuple(sorted(U)),
            'product': product
        })

# Sort by product to find the smallest good numbers
good_sets_results.sort(key=lambda x: x['product'])

print("Found Good Sets (Size 3, elements < 20):")
for i, result in enumerate(good_sets_results):
    print(f"Set: {result['set']}, Product (m): {result['product']}")

# Extract products in order
products = [result['product'] for result in good_sets_results]
print("\nList of products sorted by size:", products)

