import itertools
from sympy import primerange

def find_kth_product(k):
    primes = list(primerange(2, 50)) # We start with primes up to 50, which should be enough for the 20th smallest product P
    products = set()

    # Iterate over all combinations of 3 distinct primes
    for p1, p2, p3 in itertools.combinations(primes, 3):
        P = p1 * p2 * p3
        products.add(P)

    # Sort the unique products
    sorted_products = sorted(list(products))

    if len(sorted_products) < k:
        return None, len(sorted_products)

    kth_product = sorted_products[k - 1]
    return kth_product, len(sorted_products)

k_target = 20
P_20, count = find_kth_product(k_target)

if P_20 is not None:
    M_20 = P_20 ** 2
