    print(f"The 20th smallest good number M is: {M_20}")
else:
    print("Could not find the 20th smallest product within the initial range of primes.")

import math
from itertools import combinations

def gcd_three(a, b, c):
    return math.gcd(a, math.gcd(b, c))

def is_good_set(U):
    if len(U) < 3:
        return False

    # Condition 1: GCD of any three distinct elements is 1
    if len(U) == 3:
        a, b, c = U
        if gcd_three(a, b, c) != 1:
            return False
    # Note: The problem statement defines a good set U such that for ANY THREE distinct elements...
    # Since the search focuses on |U|=3, this check is sufficient for the search, 
    # but we should ensure the logic covers the general case if we expand beyond k=3 later.
    # For k=3, the check above is fine.

    # Condition 2: For any two distinct elements {a, b}, there exists c in U \ {a, b} such that c | ab.

    # Iterate over all pairs {a, b}
    for pair in combinations(U, 2):
        a, b = pair
        product = a * b
        found_divisor = False

        # Check against all other elements c
        for c in U:
            if c != a and c != b:
                if product % c == 0:
                    found_divisor = True
                    break

        if not found_divisor:
            return False

    return True

def find_good_numbers(limit):
    good_numbers = set()

    # Search only for sets of size 3, as these are the most common structure identified and sufficient for finding many smaller examples.
    # We enforce a < b < c to avoid duplicates.
    for a in range(2, limit + 1):
        for b in range(a + 1, limit + 1):
            for c in range(b + 1, limit + 1):
                U = (a, b, c)

                # Optimization: Condition 2 imposes strong constraints.
                # If we check the primary conditions first, it might save time, 
                # but iterating over combinations ensures correctness.

                if is_good_set(U):
                    m = a * b * c
                    good_numbers.add(m)
    return sorted(list(good_numbers))

